WITH unpacked AS (SELECT id, created_at, coupon_codes, items, ship_to, attributes, attributes['gift'] AS gift, SIZE(attributes) AS num_attributes, attributes['device'] AS device, attributes['utm_source'] AS utm_source, EXISTS(items, i -> i.price > 100) AS has_premium_item FROM carts WHERE SIZE(coupon_codes) > 2) SELECT id, created_at, coupon_codes, items, ship_to, attributes, gift, num_attributes, device, utm_source, has_premium_item, LEAD(num_attributes, 1) OVER (ORDER BY created_at, id) AS next_num_attributes, AVG(num_attributes) OVER w_recent AS num_attributes_avg_2 FROM unpacked WINDOW w_recent AS (ORDER BY num_attributes, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)
